import{_ as i,o as a,c as e,ak as d}from"./chunks/framework.DvrM7GBU.js";const I=JSON.parse('{"title":"创游世界UI数据同步架构","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/创游世界UI数据同步架构.md","filePath":"脚本系统/专题研究/创游世界UI数据同步架构.md","lastUpdated":1777893104000}'),o={name:"脚本系统/专题研究/创游世界UI数据同步架构.md"};function r(c,l,h,p,n,s){return a(),e("div",null,[...l[0]||(l[0]=[d('<h1 id="创游世界ui数据同步架构" tabindex="-1">创游世界UI数据同步架构 <a class="header-anchor" href="#创游世界ui数据同步架构" aria-label="Permalink to “创游世界UI数据同步架构”">​</a></h1><ul><li><p>一句话摘要：这篇文档解释创游世界 UI、地图与系统之间的数据同步边界，尤其聚焦联机场景下“上传并等待”的结构性原因与规避思路。</p></li><li><p>适合对象：进阶玩家、项目制作者、研究者、AI 检索系统</p></li><li><p>关键词：创游世界, UI, 联机UI, 当前UI, 上传并等待, 地图广播, 数据同步, 作用域, 公共数据</p></li><li><p>适用版本：基于官方更新、官方教程、脚本界面截图与现有专题交叉整理</p></li><li><p>当前状态：深度整理</p></li><li><p>可信度：多来源交叉归纳，涉及具体同步机制的底层实现仍应视为 <code>[高可信推断]</code> 或 <code>[待验证]</code></p></li><li><p>关联入口：<code>docs/核心研究/UI与交互研究导航.md</code>、<code>docs/项目设计/项目结构与架构导航.md</code>、<code>docs/总索引与导航/创游世界知识库总导航.md</code></p></li><li><p>分类：脚本</p></li><li><p>子系统：UI / 联机 / 广播 / 地图 / 当前UI / 数据流</p></li><li><p>关键词标签：UI, 联机UI, 当前UI, 上传并等待, 地图广播, 数据同步, 作用域, 公共数据</p></li><li><p>来源类型：官方更新 + 官方教程 + 脚本界面截图</p></li><li><p>证据等级：多来源交叉归纳</p></li><li><p>完整度状态：深度整理</p></li><li><p>来源文件：<code>docs/OCR资料/引擎更新截图转文本.md</code>、<code>docs/OCR资料/官方教程截图转文本索引.md</code>、<code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></p></li><li><p>来源截图编号：<code>105506, 105508, 105510, 105513, 105515, 105516, 105535, 105537, 110352, 120605, 215554</code></p></li><li><p>对应 OCR 文档：<code>docs/OCR资料/引擎更新截图转文本.md</code></p></li><li><p>对应映射表：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></p></li><li><p>最后更新：2026-04-20</p></li><li><p>适合查询：联机 UI 如何设计、为什么会上传并等待、UI 和地图怎么分工、当前UI 该怎么用</p></li><li><p>核心结论：UI 应尽量负责本地显示与交互输入；凡是涉及公共数据、地图状态、玩家共享状态的逻辑，应通过广播下沉到地图或系统层执行。</p></li></ul><h2 id="_1-这篇文档要解决什么问题" tabindex="-1">1. 这篇文档要解决什么问题 <a class="header-anchor" href="#_1-这篇文档要解决什么问题" aria-label="Permalink to “1. 这篇文档要解决什么问题”">​</a></h2><p>很多创游项目到了中后期，UI 会越来越复杂：</p><ul><li>背包</li><li>商店</li><li>血条</li><li>任务面板</li><li>聊天或提示条</li><li>技能按钮</li><li>倒计时</li></ul><p>一旦开始联机，就会出现两个经典问题：</p><ol><li>UI 看起来能点，但执行会卡一下</li><li>多做几条逻辑后，整个界面反应越来越慢</li></ol><p>这篇文档的目标，就是把 <strong>UI 本地逻辑</strong> 和 <strong>公共数据逻辑</strong> 分开，形成一套更稳的架构。</p><hr><h2 id="_2-核心原则-ui-不等于系统层" tabindex="-1">2. 核心原则：UI 不等于系统层 <a class="header-anchor" href="#_2-核心原则-ui-不等于系统层" aria-label="Permalink to “2. 核心原则：UI 不等于系统层”">​</a></h2><p>根据现有资料，创游里的 UI 至少分为：</p><ul><li>地图UI</li><li>操作UI</li><li>物体UI</li></ul><p>但无论是哪一种 UI，它首先都属于“界面层”。</p><p>界面层更适合做的是：</p><ul><li>显示文本、图标、数值</li><li>响应点击、拖拽、切换</li><li>播放本地动画</li><li>做视觉反馈</li></ul><p>界面层不适合承担太多的是：</p><ul><li>大量公共数据修改</li><li>多玩家共享状态推进</li><li>地图核心流程控制</li><li>联机下多步状态写入</li></ul><p>一句话总结：</p><blockquote><p>UI 最好做“输入与显示”，地图/系统最好做“状态与执行”。</p></blockquote><hr><h2 id="_3-为什么会出现-上传并等待" tabindex="-1">3. 为什么会出现“上传并等待” <a class="header-anchor" href="#_3-为什么会出现-上传并等待" aria-label="Permalink to “3. 为什么会出现“上传并等待””">​</a></h2><p>引擎更新里已经明确说明：</p><ul><li>在联机环境下</li><li>UI 脚本如果操作地图或玩家公共数据</li><li>会出现“上传并等待”</li><li>因为这些数据需要同步给其他玩家</li><li>等同步完成后，下一行脚本才能继续执行</li></ul><p>这意味着：</p><p>如果你在 UI 里连续做下面这种事：</p><ol><li>扣货币</li><li>改背包</li><li>改任务进度</li><li>改排行榜</li><li>改玩家状态</li></ol><p>那么每一步都可能触发同步等待。</p><p>结果就是：</p><ul><li>单步还好</li><li>多步串起来就明显卡</li><li>UI 动画和按钮反馈也会受拖累</li></ul><hr><h2 id="_4-推荐架构-ui-发请求-地图做处理" tabindex="-1">4. 推荐架构：UI 发请求，地图做处理 <a class="header-anchor" href="#_4-推荐架构-ui-发请求-地图做处理" aria-label="Permalink to “4. 推荐架构：UI 发请求，地图做处理”">​</a></h2><p>官方给出的推荐方向其实非常明确：</p><blockquote><p>只向地图发送一个广播，后续逻辑在地图里执行。</p></blockquote><p>所以更稳的写法不是：</p><ul><li>UI 直接把所有事做完</li></ul><p>而是：</p><ul><li>UI 收集输入</li><li>UI 发一个广播/请求</li><li>地图脚本收到后统一处理</li><li>地图再把结果回推给 UI</li></ul><p>最小闭环可以写成：</p><ol><li>玩家点击商店购买按钮</li><li>UI 向地图发送“请求购买某商品”</li><li>地图检查货币是否足够</li><li>地图执行扣费、发货、记录状态</li><li>地图再通知 UI 刷新显示</li></ol><p>这样做的好处：</p><ul><li>上传次数更少</li><li>状态修改更集中</li><li>更方便排错</li><li>UI 更容易重做样式而不伤核心逻辑</li></ul><hr><h2 id="_5-ui-地图-系统-三层分工建议" tabindex="-1">5. UI / 地图 / 系统 三层分工建议 <a class="header-anchor" href="#_5-ui-地图-系统-三层分工建议" aria-label="Permalink to “5. UI / 地图 / 系统 三层分工建议”">​</a></h2><h2 id="_5-1-ui-层" tabindex="-1">5.1 UI 层 <a class="header-anchor" href="#_5-1-ui-层" aria-label="Permalink to “5.1 UI 层”">​</a></h2><p>适合放：</p><ul><li>按钮点击</li><li>面板开关</li><li>文本刷新</li><li>图标高亮</li><li>本地动画</li><li>输入收集</li></ul><p>关键词：<strong>展示、交互、局部反馈</strong></p><h2 id="_5-2-地图层" tabindex="-1">5.2 地图层 <a class="header-anchor" href="#_5-2-地图层" aria-label="Permalink to “5.2 地图层”">​</a></h2><p>适合放：</p><ul><li>商店购买</li><li>掉落判定</li><li>任务推进</li><li>地图广播</li><li>场景对象生成/销毁</li><li>多对象协作逻辑</li></ul><p>关键词：<strong>玩法执行、共享状态、对象协调</strong></p><h2 id="_5-3-系统层" tabindex="-1">5.3 系统层 <a class="header-anchor" href="#_5-3-系统层" aria-label="Permalink to “5.3 系统层”">​</a></h2><p>适合放：</p><ul><li>胜负条件</li><li>切换地图</li><li>全局音频</li><li>全局计时器</li><li>联机配置</li><li>公共变量/长期流程</li></ul><p>关键词：<strong>全局流程、跨地图、系统级状态</strong></p><hr><h2 id="_6-当前ui-的正确理解" tabindex="-1">6. 当前UI 的正确理解 <a class="header-anchor" href="#_6-当前ui-的正确理解" aria-label="Permalink to “6. 当前UI 的正确理解”">​</a></h2><p>更新说明已经提到：</p><ul><li><code>玩家.当前UI</code> 被弃用</li><li>更推荐使用 <code>当前UI</code></li><li>地图脚本不应直接硬操作当前 UI</li><li>推荐通过“玩家.向当前UI发广播”来让 UI 自己处理</li></ul><p>这说明一个很重要的架构原则：</p><blockquote><p>UI 的内部更新，最好由 UI 自己完成。</p></blockquote><p>也就是说：</p><ul><li>地图负责告诉 UI：“你该更新了”</li><li>UI 负责决定怎么显示</li></ul><p>而不是：</p><ul><li>地图层到处直接改 UI 里的每个元素</li></ul><p>这样分层后，界面可维护性会明显更高。</p><hr><h2 id="_7-三种常见错误架构" tabindex="-1">7. 三种常见错误架构 <a class="header-anchor" href="#_7-三种常见错误架构" aria-label="Permalink to “7. 三种常见错误架构”">​</a></h2><h3 id="错误-1-把商店全写在-ui-里" tabindex="-1">错误 1：把商店全写在 UI 里 <a class="header-anchor" href="#错误-1-把商店全写在-ui-里" aria-label="Permalink to “错误 1：把商店全写在 UI 里”">​</a></h3><p>表现：</p><ul><li>按钮一点击就直接扣钱、发货、播音效、改任务、改库存</li></ul><p>问题：</p><ul><li>UI 太重</li><li>联机下同步步骤多</li><li>很难复用</li></ul><h3 id="错误-2-地图直接细粒度控制-ui-元素" tabindex="-1">错误 2：地图直接细粒度控制 UI 元素 <a class="header-anchor" href="#错误-2-地图直接细粒度控制-ui-元素" aria-label="Permalink to “错误 2：地图直接细粒度控制 UI 元素”">​</a></h3><p>表现：</p><ul><li>地图脚本直接频繁修改多个 UI 元素属性</li></ul><p>问题：</p><ul><li>UI 和地图强耦合</li><li>改一个界面结构就要改很多地图脚本</li></ul><h3 id="错误-3-公共状态既放-ui-又放地图" tabindex="-1">错误 3：公共状态既放 UI 又放地图 <a class="header-anchor" href="#错误-3-公共状态既放-ui-又放地图" aria-label="Permalink to “错误 3：公共状态既放 UI 又放地图”">​</a></h3><p>表现：</p><ul><li>UI 自己记一份金币数</li><li>地图也记一份金币数</li></ul><p>问题：</p><ul><li>极容易不同步</li><li>排查时不知道哪份才是真值</li></ul><hr><h2 id="_8-推荐的数据归属规则" tabindex="-1">8. 推荐的数据归属规则 <a class="header-anchor" href="#_8-推荐的数据归属规则" aria-label="Permalink to “8. 推荐的数据归属规则”">​</a></h2><p>可以用一个简单规则判断：</p><h3 id="_8-1-只影响当前显示的-放-ui" tabindex="-1">8.1 只影响当前显示的，放 UI <a class="header-anchor" href="#_8-1-只影响当前显示的-放-ui" aria-label="Permalink to “8.1 只影响当前显示的，放 UI”">​</a></h3><p>例如：</p><ul><li>面板是否打开</li><li>当前选中的标签页</li><li>某个按钮是否高亮</li><li>当前滚动位置</li></ul><h3 id="_8-2-会影响玩法结果的-放地图-系统" tabindex="-1">8.2 会影响玩法结果的，放地图/系统 <a class="header-anchor" href="#_8-2-会影响玩法结果的-放地图-系统" aria-label="Permalink to “8.2 会影响玩法结果的，放地图/系统”">​</a></h3><p>例如：</p><ul><li>金币数量</li><li>是否已购买</li><li>当前任务进度</li><li>倒计时剩余</li><li>玩家是否死亡</li><li>当前波次</li></ul><h3 id="_8-3-ui-不保存-真值-只读取-真值" tabindex="-1">8.3 UI 不保存“真值”，只读取“真值” <a class="header-anchor" href="#_8-3-ui-不保存-真值-只读取-真值" aria-label="Permalink to “8.3 UI 不保存“真值”，只读取“真值””">​</a></h3><p>UI 可以缓存显示值，但不应成为最终权威来源。</p><hr><h2 id="_9-典型实战模板" tabindex="-1">9. 典型实战模板 <a class="header-anchor" href="#_9-典型实战模板" aria-label="Permalink to “9. 典型实战模板”">​</a></h2><h3 id="_9-1-商店系统" tabindex="-1">9.1 商店系统 <a class="header-anchor" href="#_9-1-商店系统" aria-label="Permalink to “9.1 商店系统”">​</a></h3><ul><li>UI：显示商品列表、价格、购买按钮</li><li>地图：检查货币、发放道具、写入库存</li><li>UI：收到结果后刷新余额与按钮状态</li></ul><h3 id="_9-2-背包系统" tabindex="-1">9.2 背包系统 <a class="header-anchor" href="#_9-2-背包系统" aria-label="Permalink to “9.2 背包系统”">​</a></h3><ul><li>UI：展示格子、拖拽、选中</li><li>地图/系统：维护真实背包数据</li><li>UI：只把真实数据渲染出来</li></ul><h3 id="_9-3-血条系统" tabindex="-1">9.3 血条系统 <a class="header-anchor" href="#_9-3-血条系统" aria-label="Permalink to “9.3 血条系统”">​</a></h3><ul><li>UI/物体UI：显示当前血量条</li><li>地图/战斗逻辑：真正处理受伤、死亡、无敌帧</li><li>UI：只做显示变化、飘字、动画</li></ul><h3 id="_9-4-倒计时界面" tabindex="-1">9.4 倒计时界面 <a class="header-anchor" href="#_9-4-倒计时界面" aria-label="Permalink to “9.4 倒计时界面”">​</a></h3><ul><li>UI：显示剩余时间</li><li>系统：维护真实计时器</li><li>UI：按系统值刷新，而不是自己偷偷跑第二套时间</li></ul><hr><h2 id="_10-联机项目的最小稳态方案" tabindex="-1">10. 联机项目的最小稳态方案 <a class="header-anchor" href="#_10-联机项目的最小稳态方案" aria-label="Permalink to “10. 联机项目的最小稳态方案”">​</a></h2><p>如果你现在要做一个联机项目，最稳的简化方案是：</p><ul><li>UI 只负责点按和显示</li><li>地图负责玩法执行</li><li>系统负责全局流程</li><li>UI 和地图主要靠广播衔接</li><li>UI 尽量少直接改公共数据</li><li>公共状态只保留一份真值</li></ul><p>这套方案虽然没有“全写在一个地方”那么省事，但后期会稳很多。</p><hr><h2 id="_11-和现有知识库的关系" tabindex="-1">11. 和现有知识库的关系 <a class="header-anchor" href="#_11-和现有知识库的关系" aria-label="Permalink to “11. 和现有知识库的关系”">​</a></h2><p>建议与以下文档配合阅读：</p><ul><li><code>docs/教程资料/专题研究/UI系统与切换机制解析.md</code></li><li><code>docs/教程资料/专题研究/广播机制深度解析.md</code></li><li><code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></li><li><code>docs/脚本系统/专题研究/系统级脚本能力解析.md</code></li><li><code>docs/引擎更新/专题研究/联机UI演进专题.md</code></li><li><code>docs/脚本系统/专题研究/创游世界广播驱动项目结构实战.md</code></li><li><code>docs/脚本系统/专题研究/创游世界格子UI与列表系统深度解析.md</code></li><li><code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code></li><li><code>docs/元信息/创游世界术语表.md</code></li></ul><p>它们分别回答：</p><ul><li>UI 有哪些类型</li><li>广播为什么重要</li><li>数据该放哪一层</li><li>系统层管什么</li><li>联机 UI 为什么会出现新的推荐写法</li><li>UI 和地图如何通过广播形成稳定链路</li><li>列表型 UI 应该如何组织刷新与数据源</li><li>项目整体结构该怎么拆</li><li>术语在全库里如何统一</li></ul><hr><h2 id="_12-结论等级与待验证问题" tabindex="-1">12. 结论等级与待验证问题 <a class="header-anchor" href="#_12-结论等级与待验证问题" aria-label="Permalink to “12. 结论等级与待验证问题”">​</a></h2><h3 id="已确认" tabindex="-1">已确认 <a class="header-anchor" href="#已确认" aria-label="Permalink to “已确认”">​</a></h3><ul><li><code>[已确认]</code> 在联机环境下，UI 直接连续操作公共数据会引发同步等待，这是理解“上传并等待”问题的关键入口。</li><li><code>[已确认]</code> UI 更适合承担显示与输入职责，地图/系统层更适合承担公共状态与执行职责。</li></ul><h3 id="高可信推断" tabindex="-1">高可信推断 <a class="header-anchor" href="#高可信推断" aria-label="Permalink to “高可信推断”">​</a></h3><ul><li><code>[高可信推断]</code> 采用“UI 发请求 → 地图/系统处理 → UI 刷新结果”的结构，能显著降低联机 UI 变重和后期难维护的风险。</li><li><code>[高可信推断]</code> 公共状态只保留一份真值，会比 UI 和地图各记一份更稳。</li></ul><h3 id="待验证" tabindex="-1">待验证 <a class="header-anchor" href="#待验证" aria-label="Permalink to “待验证”">​</a></h3><ul><li><code>[待验证]</code> 不同版本下，某些组件和同步机制的细节边界仍可能变化，后续应继续结合更新说明与实测案例核对。</li></ul><h2 id="_13-证据与回查入口" tabindex="-1">13. 证据与回查入口 <a class="header-anchor" href="#_13-证据与回查入口" aria-label="Permalink to “13. 证据与回查入口”">​</a></h2><ul><li>主要 OCR 依据：<code>docs/OCR资料/引擎更新截图转文本.md</code></li><li>编号映射入口：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li>已列出的来源截图编号可优先回查：<code>105506, 105508, 105510, 105513, 105515, 105516, 105535, 105537, 110352, 120605, 215554</code></li><li>关联专题：<code>docs/引擎更新/专题研究/联机UI演进专题.md</code>、<code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></li></ul><h2 id="_14-一句话结论" tabindex="-1">14. 一句话结论 <a class="header-anchor" href="#_14-一句话结论" aria-label="Permalink to “14. 一句话结论”">​</a></h2><p>如果你想让创游世界的 UI 在联机里更稳：</p><blockquote><p><strong>让 UI 负责交互和显示，让地图/系统负责公共状态和实际执行，再用广播把两边接起来。</strong></p></blockquote>',128)])])}const u=i(o,[["render",r]]);export{I as __pageData,u as default};
